exercise.solution:
function describeValue(value) {
  if (value === null) {
    return "null";
  }

  if (Array.isArray(value)) {
    return "array";
  }

  if (Number.isNaN(value)) {
    return "NaN";
  }

  return typeof value;
}

function toNumberOrNull(text) {
  const trimmed = text.trim();

  if (trimmed === "") {
    return null;
  }

  const value = Number(trimmed);

  return Number.isFinite(value) ? value : null;
}
